//! VIA keyboard driver: discovery, keymap/encoder/custom-value reads and writes.
//! Definitions are the VIA JSON files in app/src/devices/via/keyboards/ (embedded by build.rs,
//! the frontend imports the same files) and are matched by VID/PID.

use periph_core::{self as core, serde_json::{self, Value}, Connected, DeviceInfo, Driver, Kind, Session};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::time::Duration;
use via::Keyboard;

/// Embedded VIA definitions: `(file stem, json)`. Generated by build.rs.
const DEFINITIONS: &[(&str, &str)] = include!(concat!(env!("OUT_DIR"), "/via_definitions.rs"));

#[derive(Debug, Clone)]
struct Definition {
    id: &'static str,
    rows: u8,
    cols: u8,
    encoders: u8,
    /// custom menu values: (name, channel, value id, byte length)
    values: Vec<(String, u8, u8, usize)>,
}

fn hex_u16(v: &Value) -> Option<u16> {
    let s = v.as_str()?;
    u16::from_str_radix(s.trim_start_matches("0x").trim_start_matches("0X"), 16).ok()
}

fn collect_values(v: &Value, out: &mut Vec<(String, u8, u8, usize)>) {
    match v {
        Value::Object(o) => {
            if let (Some(Value::Array(c)), Some(t)) = (o.get("content"), o.get("type").and_then(Value::as_str)) {
                if let [Value::String(name), ch, id] = c.as_slice() {
                    if let (Some(ch), Some(id)) = (ch.as_u64(), id.as_u64()) {
                        let max = o.get("options").and_then(|x| x.get(1)).and_then(Value::as_u64).unwrap_or(0);
                        let len = if t == "color" || max > 255 { 2 } else { 1 };
                        out.push((name.clone(), ch as u8, id as u8, len));
                    }
                }
            }
            o.values().for_each(|x| collect_values(x, out));
        }
        Value::Array(a) => a.iter().for_each(|x| collect_values(x, out)),
        _ => {}
    }
}

fn find_definition(vid: u16, pid: u16) -> Option<Definition> {
    DEFINITIONS.iter().find_map(|(id, text)| {
        let j: Value = serde_json::from_str(text).ok()?;
        if hex_u16(&j["vendorId"])? != vid || hex_u16(&j["productId"])? != pid {
            return None;
        }
        let rows = j["matrix"]["rows"].as_u64()? as u8;
        let cols = j["matrix"]["cols"].as_u64()? as u8;
        // encoders are marked in KLE labels as "\n\n\n\n\n\n\n\n\ne<N>"
        let encoders = text.matches("\\n\\n\\n\\n\\n\\n\\n\\n\\ne").count().max(0) as u8;
        let mut values = Vec::new();
        collect_values(&j["menus"], &mut values);
        Some(Definition { id, rows, cols, encoders, values })
    })
}

#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum KbdCmd {
    Refresh,
    SetKeycode { layer: u8, row: u8, col: u8, code: u16 },
    SetEncoder { layer: u8, encoder: u8, clockwise: bool, code: u16 },
    /// Custom menu value; `save` persists the channel to EEPROM.
    SetValue { channel: u8, id: u8, data: Vec<u8>, save: bool },
}

#[derive(Debug, Clone, Default, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct KbdState {
    pub vendor_id: u16,
    pub product_id: u16,
    pub product: String,
    pub protocol: u16,
    pub definition: Option<String>,
    pub layers: u8,
    /// [layer][row][col]
    pub keymap: Vec<Vec<Vec<u16>>>,
    /// [layer][encoder] = [counter-clockwise, clockwise]
    pub encoders: Vec<Vec<[u16; 2]>>,
    /// "channel:id" -> bytes
    pub values: BTreeMap<String, Vec<u8>>,
}

fn read_all(kb: &Keyboard, def: &Option<Definition>) -> anyhow::Result<KbdState> {
    let mut s = KbdState {
        vendor_id: kb.vendor_id,
        product_id: kb.product_id,
        product: kb.product.clone(),
        protocol: kb.protocol_version()?,
        layers: kb.layer_count()?,
        ..Default::default()
    };
    if let Some(d) = def {
        s.definition = Some(d.id.to_string());
        s.keymap = kb.keymap(s.layers, d.rows, d.cols)?;
        s.encoders = (0..s.layers)
            .map(|l| (0..d.encoders).map(|e| Ok([kb.encoder(l, e, false)?, kb.encoder(l, e, true)?])).collect())
            .collect::<anyhow::Result<_>>()?;
        for (_, ch, id, len) in &d.values {
            if let Ok(v) = kb.custom_get(*ch, *id, *len) {
                s.values.insert(format!("{ch}:{id}"), v);
            }
        }
    }
    Ok(s)
}

fn apply(kb: &Keyboard, cmd: KbdCmd) -> anyhow::Result<()> {
    match cmd {
        KbdCmd::Refresh => Ok(()),
        KbdCmd::SetKeycode { layer, row, col, code } => kb.set_keycode(layer, row, col, code),
        KbdCmd::SetEncoder { layer, encoder, clockwise, code } => kb.set_encoder(layer, encoder, clockwise, code),
        KbdCmd::SetValue { channel, id, data, save } => {
            kb.custom_set(channel, id, &data)?;
            if save {
                kb.custom_save(channel)?;
            }
            Ok(())
        }
    }
}

struct ViaSession {
    kb: Keyboard,
    def: Option<Definition>,
}

impl Session for ViaSession {
    fn read_config(&mut self) -> anyhow::Result<Value> {
        Ok(serde_json::to_value(read_all(&self.kb, &self.def)?)?)
    }
    fn apply(&mut self, cmd: Value) -> anyhow::Result<()> {
        apply(&self.kb, core::parse(cmd)?)
    }
    /// keepalive: VIA has no status report, so ping it to notice an unplug
    fn poll(&mut self) -> anyhow::Result<Option<Value>> {
        self.kb.uptime_ms().map_err(|_| anyhow::anyhow!("teclado desconectado"))?;
        Ok(None)
    }
    fn poll_interval(&self) -> Duration {
        Duration::from_secs(3)
    }
}

pub struct ViaDriver;

impl Driver for ViaDriver {
    fn info(&self) -> DeviceInfo {
        DeviceInfo { id: "via", name: "Teclado VIA", kind: Kind::Keyboard }
    }
    fn open(&self) -> anyhow::Result<(Box<dyn Session>, Connected)> {
        let kb = Keyboard::open_any()?;
        let def = find_definition(kb.vendor_id, kb.product_id);
        let info = Connected { product: kb.product.clone(), serial: String::new() };
        Ok((Box::new(ViaSession { kb, def }), info))
    }
    fn retry_interval(&self) -> Duration {
        Duration::from_secs(3)
    }
}

#[cfg(test)]
mod tests {
    #[test]
    fn example_definition_parses() {
        let d = super::find_definition(0x0000, 0x0000).expect("example-macropad.json");
        assert_eq!((d.rows, d.cols, d.encoders), (3, 4, 1));
        let ids: Vec<_> = d.values.iter().map(|v| (v.1, v.2, v.3)).collect();
        assert_eq!(ids, vec![(3, 1, 1), (3, 2, 1), (3, 3, 1), (3, 4, 2)]);
    }
}
